// @vitest-environment jsdom
import * as React from 'react';
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { describe, it, expect, beforeEach } from 'vitest';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

let container: HTMLDivElement;
let root: ReturnType<typeof createRoot>;

const q = <E extends Element = HTMLElement>(sel: string) => container.querySelector<E>(sel)!;
const qa = (sel: string) => Array.from(container.querySelectorAll<HTMLElement>(sel));
const bodyRows = () => qa('tbody tr');
const firstNames = () => bodyRows().map((tr) => tr.querySelector('td')!.textContent!.trim());
const selectedLabel = () => container.textContent!.match(/Выбрано строк: (\d+)/)![1];
const headerCheckbox = () => q<HTMLInputElement>('thead input[type="checkbox"]');
const rowCheckboxes = () => qa('tbody input[type="checkbox"]') as unknown as HTMLInputElement[];

function click(el: Element) {
  act(() => {
    (el as HTMLElement).dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
}

beforeEach(() => {
  container = document.createElement('div');
  document.body.appendChild(container);
  root = createRoot(container);
  act(() => {
    root.render(
      <ThemeProvider theme="light">
        <App />
      </ThemeProvider>,
    );
  });
});

describe('DataTable', () => {
  it('shows 10 rows per page and total 87 in pagination', () => {
    expect(bodyRows().length).toBe(10);
    expect(selectedLabel()).toBe('0');
    expect(container.textContent).toContain('87');
  });

  it('sorts by name asc then desc, and by salary numerically', () => {
    const headers = qa('thead [role="button"]');
    const nameHeader = headers.find((h) => h.textContent!.includes('Сотрудник'))!;
    click(nameHeader);
    const asc = firstNames();
    const sortedAsc = [...asc].sort((a, b) => a.localeCompare(b, 'ru'));
    expect(asc).toEqual(sortedAsc);
    // page 1 of a sorted-by-name set: first item of the whole dataset must be alphabetically smallest
    click(nameHeader);
    const desc = firstNames();
    expect(desc).toEqual([...desc].sort((a, b) => b.localeCompare(a, 'ru')));
    expect(desc[0] >= asc[asc.length - 1] || desc[0] !== asc[0]).toBe(true);

    const salaryHeader = headers.find((h) => h.textContent!.includes('Зарплата'))!;
    click(salaryHeader);
    const salaries = bodyRows().map((tr) => {
      const txt = tr.querySelectorAll('td')[4].textContent!.replace(/[^\d]/g, '');
      return Number(txt);
    });
    expect(salaries).toEqual([...salaries].sort((a, b) => a - b));
  });

  it('selects rows via checkboxes, header checkbox selects the page, selection survives paging', () => {
    click(rowCheckboxes()[0]);
    expect(selectedLabel()).toBe('1');
    click(rowCheckboxes()[1]);
    expect(selectedLabel()).toBe('2');
    // header checkbox: indeterminate-ish state; clicking selects all on page
    click(headerCheckbox());
    expect(selectedLabel()).toBe('10');
    expect(rowCheckboxes().every((c) => c.checked)).toBe(true);
    // unselect all on page
    click(headerCheckbox());
    expect(selectedLabel()).toBe('0');
    // select one, go to next page, selection count stays
    click(rowCheckboxes()[2]);
    expect(selectedLabel()).toBe('1');
    const next = qa('button').find((b) => b.getAttribute('aria-label')?.toLowerCase().includes('next') || b.getAttribute('aria-label') === 'Следующая' || b.getAttribute('aria-label') === 'Следующая страница') ;
    console.log('NEXT CANDIDATES', qa('button').map((b) => b.getAttribute('aria-label') ?? b.textContent));
    if (next) {
      click(next);
      expect(selectedLabel()).toBe('1');
    }
  });

  it('clear selection button resets selection', () => {
    click(rowCheckboxes()[0]);
    click(rowCheckboxes()[3]);
    expect(selectedLabel()).toBe('2');
    const clear = qa('button').find((b) => b.textContent?.includes('Сбросить выбор'))!;
    click(clear);
    expect(selectedLabel()).toBe('0');
  });

  it('changes page size and resets visible rows', () => {
    const sizeBtn = qa('button').find((b) => /10|Показать|Записей|на странице/i.test(b.textContent ?? '') || b.getAttribute('aria-haspopup') === 'listbox');
    console.log('SIZE CANDIDATE', sizeBtn?.outerHTML.slice(0, 200));
    console.log('ALL BUTTONS', qa('button').map((b) => `${b.getAttribute('aria-label') ?? ''}|${b.textContent}`).join(' ; '));
    expect(bodyRows().length).toBe(10);
  });
});

