const pageButton = (label: string) => qa('button').find((b) => b.textContent === label && !b.closest('[data-qa="pagination-page-sizer"]'))!;
const headerByText = (t: string) => qa('thead [role="button"]').find((h) => h.textContent!.includes(t))!;

